def box(x,y,w,h,t,f='#BBDEFB',s='#1565C0',fs=20):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="10" fill="{f}" stroke="{s}" stroke-width="3"/><text x="{x+w/2}" y="{y+h/2+7}" text-anchor="middle" font-size="{fs}" font-weight="800" fill="#0B2545" font-family="sans-serif">{t}</text>'
def ln(x1,y1,x2,y2,col='#0B2545',w=3):
    return f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{col}" stroke-width="{w}"/>'
def svg(h,body): return f'<svg viewBox="0 0 520 {h}" style="width:100%">{body}</svg>'
