S.append(goals(c,B,['Nêu <b>khái niệm, lợi ích</b> của mạng máy tính.','Phân biệt <b>LAN, WAN, Internet</b>.','Nêu chức năng <b>hub, switch, router, modem, WAP</b>.','Nhận biết các <b>cấu trúc mạng</b> (hình sao, bus, vòng).','Mô tả <b>mô hình phân tầng</b> TCP/IP và OSI.'],['Mạng máy tính','Thiết bị mạng','Cấu trúc mạng','Mô hình phân tầng','Trọng tâm, HSG']))
