S.append(S2(c,B+' · 1','Phân loại mạng theo phạm vi',RES(svg(250,box(20,20,150,60,'LAN','#C8E6C9','#2E7D32',26)+box(190,20,150,60,'MAN','#FFF9C4','#F9A825',26)+box(360,20,150,60,'WAN','#FFCCBC','#D84315',26)+'<text x="95" y="120" text-anchor="middle" font-size="20" font-weight="800" font-family="sans-serif">phòng, trường</text><text x="265" y="120" text-anchor="middle" font-size="19" font-weight="800" font-family="sans-serif">thành phố</text><text x="435" y="120" text-anchor="middle" font-size="19" font-weight="800" font-family="sans-serif">quốc gia, toàn cầu</text>'+ln(95,140,435,140)+'<text x="265" y="190" text-anchor="middle" font-size="22" font-weight="800" fill="#D84315" font-family="sans-serif">phạm vi tăng dần →</text>'),'Theo phạm vi địa lí'),card('Ghi nhớ',ul(['<b>LAN</b> (Local Area Network): trong toà nhà, trường học.','<b>WAN</b> (Wide Area Network): nối nhiều LAN, phạm vi rộng.','<b>Internet</b>: mạng của các mạng, toàn cầu.'],6))))
S.append(TB(c,B+' · 1','LAN, WAN và Internet',['Mạng','Phạm vi','Ví dụ','Sở hữu'],[['<b>LAN</b>','nhỏ (phòng, toà nhà)','mạng phòng máy','một tổ chức'],['<b>WAN</b>','lớn (tỉnh, quốc gia)','mạng ngân hàng toàn quốc','nhà cung cấp, tổ chức lớn'],['<b>Internet</b>','toàn cầu','web, thư điện tử','không ai sở hữu riêng']],note=KEY('Internet kết nối vô số LAN và WAN bằng <b>router</b> và giao thức chung <b>TCP/IP</b>.')))
S.append(S2(c,B+' · 2','Thiết bị đầu cuối và môi trường truyền',card('Thiết bị đầu cuối',ul(['Máy tính, điện thoại, máy in mạng, camera IP, thiết bị IoT.'],6))+card('Môi trường truyền',ul(['<b>Có dây</b>: cáp xoắn đôi (UTP), cáp quang.','<b>Không dây</b>: sóng vô tuyến (Wi-Fi), sóng di động.'],6)),T(tr('Môi trường','Tín hiệu','Ưu điểm',h=True)+tr('Cáp xoắn đôi','điện','rẻ, phổ biến trong LAN')+tr('Cáp quang','ánh sáng','nhanh, xa, ít nhiễu')+tr('Wi-Fi','sóng vô tuyến','tiện, di động'))))
S.append(S2(c,B+' · 2','Hub và switch',card('Hub (bộ chia tín hiệu)',ul(['Nhận tín hiệu ở một cổng, <b>phát tới mọi cổng còn lại</b>.','Dễ <b>xung đột</b>, lãng phí đường truyền.'],6))+card('Switch (bộ chuyển mạch)',ul(['Biết máy nào ở cổng nào (theo <b>địa chỉ MAC</b>).','Chỉ gửi <b>đúng cổng</b> cần thiết.'],6)),KEY('Hub và switch chỉ nối các máy trong <b>cùng một LAN</b>. Switch hiệu quả hơn hub nên hầu như thay thế hoàn toàn hub.')))
