S.append(S2(c,B+' · 2','Router (bộ định tuyến)',card('Chức năng',ul(['Nối <b>các mạng khác nhau</b> (LAN với Internet).','Chọn <b>đường đi</b> cho dữ liệu: <b>định tuyến</b> (routing).','Cổng <b>LAN</b> nối mạng nội bộ, cổng <b>WAN</b> nối ra ngoài.'],6)),KEY('Router của gia đình thường kiêm <b>switch</b>, <b>điểm truy cập Wi-Fi</b> và <b>cấp địa chỉ IP</b> (DHCP).')+WARN('Không thể dùng hub/switch để nối hai LAN ở xa nhau qua Internet: cần <b>router</b>.')))
