S.append(S2(c,B+' · 2','Modem và điểm truy cập không dây (WAP)',card('Modem',ul(['Chuyển đổi tín hiệu <b>số ↔ tương tự</b> (điều chế – giải điều chế).','Dùng nối LAN với <b>nhà cung cấp dịch vụ</b> (ADSL, cáp quang, 4G/5G).'],6)),card('Điểm truy cập không dây (WAP)',ul(['Phát <b>Wi-Fi</b> để thiết bị kết nối không dây vào LAN.','Có tên mạng <b>SSID</b> và mật khẩu.'],6))+KEY('Tại nhà: <b>modem + router + WAP</b> thường tích hợp trong <b>một thiết bị</b>.')))
S.append(TB(c,B+' · 2','Tổng hợp thiết bị mạng',['Thiết bị','Chức năng chính','Phạm vi'],[['Hub','phát tín hiệu tới mọi cổng','trong LAN'],['<b>Switch</b>','chuyển dữ liệu đúng cổng','trong LAN'],['<b>Router</b>','nối mạng, chọn đường','giữa các mạng'],['Modem','đổi tín hiệu số ↔ tương tự','LAN ↔ nhà cung cấp'],['WAP','phát Wi-Fi','mở rộng LAN']],note=KEY('Dễ nhầm: <b>switch nối máy trong LAN</b>, <b>router nối LAN với mạng khác</b>.')))
S.append(S2(c,B+' · 3','Cấu trúc mạng (topology)',card('Khái niệm',ul(['<b>Cấu trúc mạng</b> (topology): cách bố trí, kết nối các thiết bị.','Ba dạng cơ bản: <b>hình sao</b>, <b>hình tuyến (bus)</b>, <b>hình vòng</b>.'],6)),KEY('Ngày nay LAN dùng nhiều nhất cấu trúc <b>hình sao</b> với <b>switch</b> ở trung tâm.')))
S.append(S2(c,B+' · 3','Ba cấu trúc cơ bản',RES(svg(240,box(205,90,100,40,'Switch','#C8E6C9','#2E7D32',20)+ln(255,90,255,40)+ln(255,130,255,185)+ln(220,110,150,110)+ln(290,110,360,110)+box(220,0,70,38,'A')+box(220,185,70,38,'B')+box(80,90,70,40,'C')+box(360,90,70,40,'D')+'<text x="255" y="236" text-anchor="middle" font-size="22" font-weight="800" font-family="sans-serif" fill="#D84315">HÌNH SAO</text>'),'Hình sao: nút trung tâm'),T(tr('Dạng','Đặc điểm',h=True)+tr('<b>Sao</b>','nối vào thiết bị trung tâm; hỏng một máy không ảnh hưởng')+tr('<b>Bus</b>','mọi máy chung một đường trục; đứt trục là hỏng cả mạng')+tr('<b>Vòng</b>','các máy nối thành vòng kín; dữ liệu đi theo một chiều'))))
S.append(TB(c,B+' · 3','So sánh các cấu trúc mạng',['Tiêu chí','Sao','Bus','Vòng'],[['Thiết bị trung tâm','có (switch)','không','không'],['Một máy hỏng','mạng vẫn chạy','vẫn chạy','dễ ảnh hưởng cả vòng'],['Đứt dây chính','chỉ máy đó mất','<b>cả mạng</b> hỏng','<b>cả vòng</b> hỏng'],['Mở rộng','dễ','khó','trung bình'],['Sử dụng ngày nay','<b>phổ biến nhất</b>','hiếm','hiếm']],note=WARN('Nhược điểm hình sao: thiết bị trung tâm hỏng thì <b>cả mạng</b> ngừng.')))
S.append(S2(c,B+' · 4','Vì sao cần mô hình phân tầng?',card('Ý tưởng',ul(['Truyền dữ liệu là việc <b>phức tạp</b>: chia thành các <b>tầng</b>, mỗi tầng một nhiệm vụ.','Tầng trên dùng dịch vụ của tầng dưới.','Thay đổi một tầng <b>không ảnh hưởng</b> các tầng khác.'],6)),KEY('Ví dụ: gửi thư. Viết thư → bỏ vào phong bì ghi địa chỉ → bưu cục chọn tuyến → xe vận chuyển. Mỗi bước là một “tầng”.')))
S.append(TB(c,B+' · 4','Mô hình TCP/IP (4 tầng)',['Tầng','Nhiệm vụ','Giao thức'],[['<b>Ứng dụng</b>','giao tiếp với người dùng','HTTP, HTTPS, SMTP, DNS, FTP'],['<b>Giao vận</b>','truyền tin cậy giữa hai tiến trình','TCP, UDP'],['<b>Internet</b>','đánh địa chỉ và chọn đường','IP, ICMP'],['<b>Truy cập mạng</b>','truyền bit trên đường truyền','Ethernet, Wi-Fi']],note=KEY('Đọc từ <b>trên xuống</b>: Ứng dụng → Giao vận → Internet → Truy cập mạng.')))
S.append(TB(c,B+' · 4','Mô hình OSI (7 tầng)',['Số','Tầng','Ý nghĩa'],[['7','Ứng dụng (Application)','dịch vụ cho người dùng'],['6','Trình diễn (Presentation)','mã hoá, nén'],['5','Phiên (Session)','quản lí phiên làm việc'],['4','Giao vận (Transport)','truyền tin cậy'],['3','Mạng (Network)','địa chỉ IP, định tuyến'],['2','Liên kết dữ liệu (Data Link)','địa chỉ MAC, khung'],['1','Vật lí (Physical)','bit trên đường truyền']],note=KEY('Mẹo nhớ OSI từ 7 → 1: <b>Ứng – Trình – Phiên – Giao – Mạng – Liên – Vật</b>.')))
S.append(S2(c,B+' · 4','Đóng gói dữ liệu (encapsulation)',card('Quá trình gửi',ul(['Mỗi tầng <b>thêm tiêu đề (header)</b> của mình vào dữ liệu.','Tầng giao vận: <b>đoạn</b> (segment).','Tầng Internet: <b>gói</b> (packet) có địa chỉ IP.','Tầng truy cập: <b>khung</b> (frame) có địa chỉ MAC.'],6)),KEY('Bên nhận làm <b>ngược lại</b>: bóc từng lớp tiêu đề từ dưới lên (<b>giải đóng gói</b>).')+OK('Giống gói hàng: bọc nhiều lớp phong bì, mỗi lớp ghi thông tin vận chuyển riêng.')))
S+=END(c,B,['<b>LAN</b> nhỏ, <b>WAN</b> rộng, <b>Internet</b> toàn cầu.','<b>Switch</b> nối máy trong LAN; <b>router</b> nối các mạng và định tuyến.','<b>Modem</b> đổi tín hiệu số ↔ tương tự; <b>WAP</b> phát Wi-Fi.','Cấu trúc: <b>sao</b> (phổ biến), bus, vòng.','TCP/IP 4 tầng, OSI 7 tầng; dữ liệu được <b>đóng gói</b> từng tầng.'],[('Nối máy trong LAN','switch'),('Nối hai mạng','router'),('Địa chỉ phần cứng','MAC'),('Địa chỉ logic','IP')],'Nhầm switch với router.',['Switch dùng <b>MAC</b> (tầng 2), router dùng <b>IP</b> (tầng 3).','Hub là thiết bị tầng 1 (vật lí).','Cấu trúc <b>lưới</b> (mesh) bền nhưng tốn dây.','Router mặc định dùng <b>cổng mặc định</b> (default gateway).'],['<b>VLAN</b> chia switch thành nhiều mạng logic.','<b>NAT</b> cho nhiều máy dùng chung một IP công cộng.','<b>PoE</b> cấp nguồn qua cáp mạng.'],
 [('Mạng máy tính là gì? Nêu hai lợi ích.',),('Phân biệt hub và switch.',),('Router dùng để làm gì? Vì sao cần cổng WAN?',),('Kể tên 3 cấu trúc mạng cơ bản.',),('Kể tên các tầng của mô hình TCP/IP.',)],
 [('Các máy tính nối với nhau để trao đổi dữ liệu; lợi ích: chia sẻ tài nguyên, trao đổi thông tin.',),('Hub phát tới <b>mọi cổng</b>; switch chỉ gửi <b>đúng cổng</b> đích.',),('Nối các mạng, định tuyến; cổng WAN nối ra mạng ngoài.',),('Hình sao, bus, vòng.',),('Ứng dụng, Giao vận, Internet, Truy cập mạng.',)],
 [('Tại sao hầu hết LAN hiện nay chọn cấu trúc hình sao?',),('Một LAN dùng hub, 4 máy: A gửi cho B thì máy nào nhận được tín hiệu? Nếu dùng switch thì sao?',),('Đúng hay sai: (a) Switch nối được hai LAN ở xa qua Internet. (b) Modem đổi tín hiệu số sang tương tự. (c) Tầng giao vận gồm TCP và UDP. (d) Cáp quang truyền bằng điện.',),('Vì sao nói Internet là “mạng của các mạng”?',),('Sắp xếp theo thứ tự đóng gói khi gửi: khung, đoạn, gói, dữ liệu ứng dụng.',),('Thiết bị nào hoạt động ở tầng mạng của OSI? Tầng liên kết dữ liệu?',)],
 [('Dễ mở rộng, một máy hỏng không ảnh hưởng, dễ tìm lỗi, dùng switch hiệu quả.',),('Hub: cả B, C, D nhận (chỉ B xử lí); switch: chỉ B.',),('(a) <b>Sai</b>: cần router. (b) <b>Đúng</b>. (c) <b>Đúng</b>. (d) <b>Sai</b>: ánh sáng.',),('Internet kết nối vô số mạng riêng lẻ bằng router và giao thức chung TCP/IP.',),('Dữ liệu ứng dụng → đoạn → gói → khung.',),('Router: tầng mạng (3); switch: tầng liên kết dữ liệu (2).',)],hper=2)
